namespace Intropy.Topology.Generation.Test;

public class IntropyGenerateTests
{
    private static readonly System.Reflection.Assembly s_assembly = typeof(OrderSystem).Assembly;

    [Fact]
    public async Task RunAsync_Check_ShouldReturnZeroForValidSystem()
    {
        // Act
        var (code, _) = await Capture(() => IntropyGenerate.RunAsync(s_assembly, ["check"]));

        // Assert
        Assert.Equal(0, code);
    }

    [Fact]
    public async Task RunAsync_Graph_ShouldEmitTopologyJson()
    {
        // Act
        var (code, output) = await Capture(() => IntropyGenerate.RunAsync(s_assembly, ["graph"]));

        // Assert
        Assert.Equal(0, code);
        Assert.Contains("\"systemName\": \"order-fulfillment\"", output, StringComparison.Ordinal);
    }

    [Fact]
    public async Task REDACTED()
    {
        // Act — graph is presentation: camelCase, kebab-case kinds, short contract names,
        // empty collections omitted. The wire format stays plain model serialization.
        var (_, output) = await Capture(() => IntropyGenerate.RunAsync(s_assembly, ["graph"]));

        // Assert
        Assert.Contains("\"kind\": \"extractor\"", output, StringComparison.Ordinal);
        Assert.Contains("\"contract\": \"RawOrder\"", output, StringComparison.Ordinal);
        Assert.Contains("\"pubsub\": \"pubsub-a\"", output, StringComparison.Ordinal);
        Assert.Contains("\"direction\": \"in\"", output, StringComparison.Ordinal);
        // Connector entries carry the resolved transport's Dapr type.
        Assert.Contains("\"transport\": \"bindings.localstorage\"", output, StringComparison.Ordinal);
        Assert.DoesNotContain("\"Kind\":", output, StringComparison.Ordinal);
        Assert.DoesNotContain("ContractTypeName", output, StringComparison.Ordinal);
        // The extractor subscribes to nothing: the empty collection is omitted, not printed.
        Assert.DoesNotContain("\"subscribes\": []", output, StringComparison.Ordinal);
    }

    [Fact]
    public async Task RunAsync_Graph_ShouldShowScheduleOnlyForScheduledComponents()
    {
        // Act — order-extractor declares a schedule; the other components do not.
        var (_, output) = await Capture(() => IntropyGenerate.RunAsync(s_assembly, ["graph"]));

        // Assert
        Assert.Contains("\"schedule\": \"*/5 * * * *\"", output, StringComparison.Ordinal);
        Assert.Equal(1, output.Split("\"schedule\"").Length - 1);
    }

    [Fact]
    public async Task RunAsync_Generate_ShouldWriteArtifactsToDirectory()
    {
        // Arrange
        var dir = Path.Combine(Path.GetTempPath(), "intropy-gen-test-" + Guid.NewGuid().ToString("N"));
        try
        {
            // Act
            var (code, _) = await Capture(() => IntropyGenerate.RunAsync(s_assembly, ["generate", dir]));

            // Assert
            Assert.Equal(0, code);
            Assert.True(File.Exists(Path.Combine(dir, "components", "pubsub-a.yaml")));
            Assert.True(File.Exists(Path.Combine(dir, "config", "order-extractor.intropy.json")));
        }
        finally
        {
            if (Directory.Exists(dir))
            {
                Directory.Delete(dir, recursive: true);
            }
        }
    }

    [Fact]
    public async Task RunAsync_UnknownVerb_ShouldReturnNonZero()
    {
        // Act
        var (code, _) = await Capture(() => IntropyGenerate.RunAsync(s_assembly, ["wat"]));

        // Assert
        Assert.Equal(2, code);
    }

    private static async Task<(int Code, string Output)> Capture(Func<Task<int>> run)
    {
        var original = Console.Out;
        using var writer = new StringWriter();
        Console.SetOut(writer);
        try
        {
            var code = await run();
            return (code, writer.ToString());
        }
        finally
        {
            Console.SetOut(original);
        }
    }
}

namespace Intropy.Topology.Model;

/// <summary>
/// A topic materialized from usage, with both sides of the edge precomputed
/// (<see cref="Publishers"/> and <see cref="Subscribers"/> feed the future Dapr pubsub
/// component's <c>scopes</c>).
/// </summary>
public sealed record TopicResource
{
    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }

    /// <summary>Full name of the event contract type carried on the topic.</summary>
    public required string ContractTypeName { get; init; }

    /// <summary>Names of components publishing to the topic (sorted).</summary>
    public required IReadOnlyList<string> Publishers { get; init; }

    /// <summary>Names of components subscribed to the topic (sorted).</summary>
    public required IReadOnlyList<string> Subscribers { get; init; }
}

/// <summary>A system-owned connector materialized from usage.</summary>
public sealed record ConnectorResource
{
    /// <summary>The connector's name (DNS-1123 label).</summary>
    public required string Name { get; init; }

    /// <summary>The transport — the kind of Dapr binding the connector materializes as.</summary>
    public required Transport Transport { get; init; }

    /// <summary>The derived Dapr binding component name: <c>binding.&lt;connector-name&gt;</c>.</summary>
    public string DaprComponentName => $"binding.{Name}";

    /// <summary>The union of directions the connector is used in.</summary>
    public required IReadOnlyList<ConnectorDirection> Directions { get; init; }

    /// <summary>Names of components using the connector (sorted).</summary>
    public required IReadOnlyList<string> UsedBy { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>
/// The immutable, validated topology of one integration system: its components (in
/// declaration order) and the resources materialized from their usage (sorted).
/// Plain serializable data — generation tooling consumes this model.
/// </summary>
public sealed record SystemTopology
{
    /// <summary>The system's name (DNS-1123 label).</summary>
    public required string SystemName { get; init; }

    /// <summary>All components, in declaration order.</summary>
    public required IReadOnlyList<ComponentModel> Components { get; init; }

    /// <summary>Topics materialized from publish and subscribe edges.</summary>
    public required IReadOnlyList<TopicResource> Topics { get; init; }

    /// <summary>Connectors materialized from connector usage.</summary>
    public required IReadOnlyList<ConnectorResource> Connectors { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>
/// One component in the system: an integration block or a container service, together
/// with all of its edges and one activation attribute — an optional cron schedule
/// (decision 0010). Everything else about the workload shape (hosting model, ports,
/// process lifetime) lives in the component's own scaffold, not in the topology.
/// </summary>
public sealed record ComponentModel
{
    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public required string Name { get; init; }

    /// <summary>The component kind this component was declared as.</summary>
    public required ComponentKind Kind { get; init; }

    /// <summary>The cron schedule that activates the component; null when it runs once
    /// at host start.</summary>
    public required string? Schedule { get; init; }

    /// <summary>Topics the component subscribes to.</summary>
    public required IReadOnlyList<TopicSubscription> Subscribes { get; init; }

    /// <summary>Topics the component publishes to, by output port.</summary>
    public required IReadOnlyList<PublishEdge> Publishes { get; init; }

    /// <summary>Connectors the component uses (explicit From/To usage).</summary>
    public required IReadOnlyList<ConnectorEdge> Connectors { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>A topic a component subscribes to.</summary>
public sealed record TopicSubscription
{
    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }
}

/// <summary>A component publishing to a topic through a named output port.</summary>
public sealed record PublishEdge
{
    /// <summary>The output port name (<c>default</c> when no port was given).</summary>
    public required string Port { get; init; }

    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }
}

